{
    /// <summary>
    /// Returns new chats added to a shareable chat folder by its owner. The method must be called at most once in getOption("chat_folder_new_chats_update_period") for the given chat folder
    /// </summary>
    public Task<TdLib.TdApi.Objects.Chats> GetChatFolderNewChatsAsync(int chatFolderId = default)
    {

           using var activity =  StartCallActivity("GetChatFolderNewChatsAsync", typeof(GetChatFolderNewChats).FullName ?? "GetChatFolderNewChatsAsync");

           try
           {
             return client.GetChatFolderNewChatsAsync(chatFolderId);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
